; DATOS fichas_de_objeto: Nueve fichas de once bytes: 0xAAFD, 0xAB08, 0xAB13,
;   0xAB1E, 0xAB29, 0xAB34, 0xAB3F, 0xAB4A y 0xAB55, y la novena acaba justo
;   en 0xAB60. El bucle de 0x422C rellena las cuatro primeras con dos bytes
;   sacados de 0xC610 y deja un 3 en el tercer byte de cada una; ese 3 esta
;   puesto tambien en las cinco de atras. Los campos que usa el codigo (rutina
;   de 0x4C1F, que indexa con A-1): 1 = X, 2 = Y, 3 = estado, 4 = fotograma, 5
;   = parpadeo.
